// Boxed allocation — 40 bytes on a 64-bit process
// (8-byte header + 4-byte int + padding)
object boxedInt = 42;

int unboxed = (int)boxedInt; // no new allocation

// Common boxing traps:

// 1. Casting to object
void Log(object value)
{
    Console.WriteLine(value);
}
Log(42); // boxes int here

// 2. Non-generic collections
ArrayList list = new ArrayList();
list.Add(42); // boxes int here
list.Add("text"); // reference type, no boxing

// 3. Calling non-generic interface methods
var comparer = Comparer.Default;
int result = comparer.Compare(1, 2); // boxes ints here

using BenchmarkDotNet.Attributes;
using BenchmarkDotNet.Running;

[MemoryDiagnoser]
public class BoxingBenchmarks
{
    private int _value = 42;

    [Benchmark]
    public string StringConcat()
    {
        string s = "";
        for (int i = 0; i < 1000; i++)
            s += i; // allocates new string each iteration
        return s;
    }

    [Benchmark]
    public string StringBuilder()
    {
        var sb = new System.Text.StringBuilder();
        for (int i = 0; i < 1000; i++)
            sb.Append(i); // no per-iteration allocation
        return sb.ToString();
    }
}

BenchmarkRunner.Run<BoxingBenchmarks>();

static T Max<T>(T a, T b) where T : IComparable<T>
{
    // IComparable<T> is generic — no boxing when T is a value type
    return a.CompareTo(b) > 0 ? a : b;
}

int maxInt = Max(10, 20);      // no boxing
DateTime maxDate = Max(d1, d2); // no boxing

// Compare with non-generic IComparable:
static T MaxLegacy<T>(T a, T b) where T : IComparable
{
    // IComparable.CompareTo takes object — boxes value types
    return a.CompareTo((object)b) > 0 ? a : b;
}
